watch.code:
shelves = sorted(shelves)
lo = 0
hi = len(shelves) - 1
while lo <= hi:
    mid = (lo + hi) // 2
    if shelves[mid] == 4:
        break
    elif shelves[mid] < 4:
        lo = mid + 1
    else:
        hi = mid - 1
print(mid if shelves[mid] == 4 else -1)

